function localizedBase(q: any, locale: EcoLocaleV1, stem: string, options: string[], explanation: string): EcoLocalizedQuestionV1 {
  return {
    ...q,
    questionId: locale === "en" ? q.questionId : `${q.questionId}-${locale.toUpperCase()}`,
    stem, options, canonicalAnswer: options[q.correctIndex], explanation, locale,
    localizationV1: { version: ECO_LOCALIZATION_V1, englishQuestionId: q.questionId, semanticInvariant: true, cpInvariant: true, qlInvariant: true, difficultyInvariant: true, sourceInvariant: true, optionOrderInvariant: true, correctIndexInvariant: true, reviewOnly: true },
  };
}

function cp7Option(text: string, locale: NativeLocale): string {
  if (/^(?:\d+|M[1-4])$/u.test(text)) return text;
  if (["Fiat money", "Legal tender", "Reserve money", "High-powered money", "Narrow money", "Broad money", "Money multiplier"].includes(text)) return text;
  const hit = CP7_OPTIONS[text];
  if (hit) return hit[locale];
  throw new Error(`Unsupported CP007 option for ${locale}: ${text}`);
}

